package gr.argyrismitsos.fleetindependentclient;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.annotation.SuppressLint;import org.json.*;import java.io.*;import java.net.*;import java.util.*;

/** Separate install, one owner-configured HTTPS origin; end users see only username/password. */
public final class IndependentClientActivity extends Activity {
 private WebView web;private String endpoint="";private ValueCallback<Uri[]> files;private byte[] export;private String transientToken="";private final java.util.concurrent.ExecutorService work=java.util.concurrent.Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle state){super.onCreate(state);endpoint=getSharedPreferences("independent",MODE_PRIVATE).getString("endpoint","");if(endpoint.isEmpty())setup();else open();}
 private static String endpoint(String address)throws Exception{URI uri=new URI(address.trim());if(!uri.getScheme().equals("https")||uri.getHost()==null||!uri.getHost().matches("[a-z0-9-]+\\.duckdns\\.org")||uri.getUserInfo()!=null||uri.getPort()!=-1&&uri.getPort()!=443||uri.getRawQuery()!=null||uri.getFragment()!=null||!Arrays.asList("","/").contains(uri.getPath()))throw new Exception("Χρειάζεται το καταχωρισμένο HTTPS όνομα του ανεξάρτητου Server.");return "https://"+uri.getHost();}
 private void setup(){LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(32,48,32,32);TextView label=new TextView(this);label.setText("Ρύθμιση από ιδιοκτήτη — μόνο μία φορά σε αυτή τη δοκιμαστική εγκατάσταση. Οι χρήστες θα συνδέονται μόνο με username και password.");layout.addView(label);EditText address=new EditText(this);address.setHint("HTTPS διεύθυνση που επέλεξε ο ιδιοκτήτης");layout.addView(address);EditText user=new EditText(this);user.setHint("Username ιδιοκτήτη");layout.addView(user);EditText password=new EditText(this);password.setHint("Password");password.setInputType(129);layout.addView(password);Button save=new Button(this);save.setText("Έλεγχος και ρύθμιση ανεξάρτητου Server");layout.addView(save);setContentView(layout);save.setOnClickListener(v->{String url=address.getText().toString(),u=user.getText().toString(),p=password.getText().toString();password.setText("");save.setEnabled(false);work.execute(()->{try{String origin=endpoint(url);HttpURLConnection connection=(HttpURLConnection)new URL(origin+"/api/auth/user-login").openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(20000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] body=new JSONObject().put("username",u).put("password",p).put("deviceName","Independent Client owner setup").toString().getBytes("UTF-8");try{connection.setFixedLengthStreamingMode(body.length);try(OutputStream out=connection.getOutputStream()){out.write(body);}if(connection.getResponseCode()!=200)throw new Exception("Ο ιδιοκτήτης δεν επιβεβαιώθηκε ή ο Server είναι εκτός σύνδεσης.");JSONObject login=new JSONObject(read(connection.getInputStream(),1024*1024));if(!login.getJSONObject("user").optString("role").equals("owner"))throw new Exception("Η ρύθμιση απαιτεί λογαριασμό ιδιοκτήτη.");getSharedPreferences("independent",MODE_PRIVATE).edit().putString("endpoint",origin).commit();endpoint=origin;transientToken=login.getString("token");String cookie=connection.getHeaderField("Set-Cookie");if(cookie!=null)android.webkit.CookieManager.getInstance().setCookie(origin,cookie);runOnUiThread(this::open);}finally{connection.disconnect();}}catch(Exception error){runOnUiThread(()->{label.setText(error.getMessage()==null?"Η σύνδεση δεν επιβεβαιώθηκε.":error.getMessage());save.setEnabled(true);});}});});}
 @SuppressLint("SetJavaScriptEnabled") private void open(){web=new WebView(this);setContentView(web);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);android.webkit.CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Bridge(),"AndroidFleet");
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,String url){return !same(url);}@Override public void onReceivedSslError(WebView view,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();Toast.makeText(IndependentClientActivity.this,"Μη έγκυρο πιστοποιητικό HTTPS. Η σύνδεση αποκλείστηκε.",Toast.LENGTH_LONG).show();}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){if(!same(request.getUrl().toString()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));return null;}});
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(files!=null)files.onReceiveValue(null);files=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(intent,1);return true;}});web.loadUrl(endpoint+"/");
 }
 private boolean same(String value){try{return new URI(endpoint).getHost().equals(new URI(value).getHost())&&value.startsWith(endpoint+"/");}catch(Exception error){return false;}}
 private static String read(InputStream input,int limit)throws Exception{try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new IOException("Oversized response");out.write(buffer,0,n);}return new String(out.toByteArray(),"UTF-8");}}
 private byte[] decode(String data){if(data.length()>32*1024*1024)throw new IllegalArgumentException("Oversized export");byte[] bytes=android.util.Base64.decode(data,android.util.Base64.DEFAULT);if(bytes.length>24*1024*1024)throw new IllegalArgumentException("Oversized export");return bytes;}
 private void save(byte[] bytes,String name,String type){runOnUiThread(()->{if(export!=null){Toast.makeText(this,"Ολοκλήρωσε την προηγούμενη εξαγωγή.",Toast.LENGTH_LONG).show();return;}export=bytes;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType(type);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[/\\\\]","_"));startActivityForResult(intent,2);});}
 public final class Bridge {
  @JavascriptInterface public String getPlatform(){return "android";}
  @JavascriptInterface public String getAuthToken(){return transientToken;}
  @JavascriptInterface public void saveAuthToken(String token,boolean remember){transientToken=token==null?"":token;}
  @JavascriptInterface public void clearAuthToken(){transientToken="";}
  @JavascriptInterface public void openFleet(){runOnUiThread(()->web.loadUrl(endpoint+"/fleet.html?embedded=1"));}
  @JavascriptInterface public void savePdf(String base64,String name){save(decode(base64),name,"application/pdf");}
  @JavascriptInterface public void exportHistoryExcel(String base64,String name){save(decode(base64),name,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");}
  @JavascriptInterface public void exportDiagnosticReport(String json){save(json.getBytes(java.nio.charset.StandardCharsets.UTF_8),"Fleet_Diagnostics.json","application/json");}
  @JavascriptInterface public void openPdf(String base64,String name){byte[] bytes=decode(base64);work.execute(()->{try{File file=new File(getCacheDir(),UUID.randomUUID().toString()+".pdf");try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}Uri uri=Uri.parse("content://gr.argyrismitsos.fleetindependentclient.reports/"+file.getName());runOnUiThread(()->{Intent open=new Intent(Intent.ACTION_VIEW);open.setDataAndType(uri,"application/pdf");open.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(open);}catch(ActivityNotFoundException missing){save(bytes,name,"application/pdf");}});}catch(Exception error){runOnUiThread(()->Toast.makeText(IndependentClientActivity.this,"Δεν άνοιξε το PDF.",Toast.LENGTH_LONG).show());}});}
  @JavascriptInterface public void exportInvoiceZip(String json,String token){work.execute(()->{try{JSONArray list=new JSONObject(json).getJSONArray("files");if(list.length()>200)throw new IOException("Μεγάλη εξαγωγή");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(bytes)){for(int i=0;i<list.length();i++){JSONObject item=list.getJSONObject(i);String key=item.getString("key");if(!key.startsWith("service-documents/")||key.contains(".."))throw new IOException("Invalid private key");HttpURLConnection connection=(HttpURLConnection)new URL(endpoint+"/api/service-documents/"+Uri.encode(key,"/")).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(30000);connection.setRequestProperty("Authorization","Bearer "+token);try{if(connection.getResponseCode()!=200)throw new IOException("Η πρόσβαση αρχείου δεν επιβεβαιώθηκε.");String name=(i+1)+"_"+item.optString("name","invoice.pdf").replaceAll("[/\\\\]","_");zip.putNextEntry(new java.util.zip.ZipEntry(name));try(InputStream input=connection.getInputStream()){byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1){if(bytes.size()+n>24*1024*1024)throw new IOException("Μεγάλη εξαγωγή");zip.write(buffer,0,n);}}zip.closeEntry();}finally{connection.disconnect();}}}save(bytes.toByteArray(),"Fleet_Invoices.zip","application/zip");}catch(Exception error){runOnUiThread(()->Toast.makeText(IndependentClientActivity.this,"Η εξαγωγή δεν ολοκληρώθηκε.",Toast.LENGTH_LONG).show());}});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==1&&files!=null){List<Uri> values=new ArrayList<Uri>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)values.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)values.add(data.getData());}files.onReceiveValue(values.toArray(new Uri[0]));files=null;}if(request==2){byte[] bytes=export;export=null;if(result==RESULT_OK&&data!=null&&bytes!=null)work.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"w")){if(out==null)throw new IOException();out.write(bytes);runOnUiThread(()->Toast.makeText(this,"Το αρχείο αποθηκεύτηκε.",Toast.LENGTH_SHORT).show());}catch(Exception error){runOnUiThread(()->Toast.makeText(this,"Η αποθήκευση απέτυχε.",Toast.LENGTH_LONG).show());}});}}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("AndroidFleet");web.destroy();}transientToken="";work.shutdown();super.onDestroy();}
}
